import { defineConfig } from 'prisma/config';

// =============================================================================
// Prisma configuration of the bare host
// =============================================================================
//
// `prisma/schema/` and `prisma/migrations/` are GENERATED by
// `scripts/prepare-db.mjs` (the platform fragments of `@marinoscar/platform-db`
// plus the domain fragments and migrations of `@marinoscar/kvox-db`); nothing
// under `prisma/` is committed. The URL comes from the environment: generating
// a client needs none, and `src/db.ts` sets `DATABASE_URL` to the database it
// started before it runs `prisma migrate deploy`.
// =============================================================================

export default defineConfig({
  schema: 'prisma/schema',
  datasource: {
    url: process.env.DATABASE_URL ?? 'postgresql://postgres:postgres@127.0.0.1:5432/postgres',
  },
  migrations: {
    path: 'prisma/migrations',
  },
});
